namespace CleanArchitecture.Blazor.Application.Features.ITSystems.Commands.Create;

public class CreateITSystemCommandValidator : AbstractValidator<CreateITSystemCommand>
{
    public CreateITSystemCommandValidator()
    {
        RuleFor(x => x.Name)
            .NotEmpty()
            .MaximumLength(100)
            .WithMessage("Name is required and must be less than 100 characters.");

        RuleFor(x => x.Description)
            .MaximumLength(500)
            .WithMessage("Description must be less than 500 characters.");

        RuleFor(x => x.Owner)
            .MaximumLength(100)
            .WithMessage("Owner must be less than 100 characters.");

        RuleFor(x => x.Version)
            .MaximumLength(50)
            .WithMessage("Version must be less than 50 characters.");

        RuleFor(x => x.Status)
            .MaximumLength(50)
            .WithMessage("Status must be less than 50 characters.");

        RuleFor(x => x.Category)
            .MaximumLength(100)
            .WithMessage("Category must be less than 100 characters.");

        RuleFor(x => x.Vendor)
            .MaximumLength(100)
            .WithMessage("Vendor must be less than 100 characters.");

        RuleFor(x => x.CriticalityLevel)
            .MaximumLength(50)
            .WithMessage("Criticality Level must be less than 50 characters.");

        RuleFor(x => x.AnnualCost)
            .GreaterThanOrEqualTo(0)
            .When(x => x.AnnualCost.HasValue)
            .WithMessage("Annual Cost must be greater than or equal to 0.");
    }
}